mapper.select:
select T1.* from TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.trade_id = t2.trade_id LEFT JOIN PTL_PORTFOLIO T3 ON T3.PORTFOLIO_ID = T2.PORTFOLIO_ID WHERE 1=1
and T1.TOTLE_TRADE_ID = #{totleTradeId}
and T1.TRADE_ID = #{tradeId}

mapper.insert:
INSERT INTO TRD_PRODUCT_DEAL_ADD (TRADE_ID, PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) SELECT TRADE_ID || 'R', PORTFOLIO_ID, CUSTOM_CASH_TYPE, GEN_TYPE, PUR_CFM_DATE, RED_CFM_DATE, REG_DATE_AMT,
REG_DATE, BONUS_CFM_DATE, ENTRUST_ID, PAY_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, #{updateUser}, CURRENT_TIMESTAMP FROM TRD_PRODUCT_DEAL_ADD where TRADE_ID = #{bizCode}

mapper.select:
SELECT t1.PROD_REGIST_CODE
FROM FIN_PRODUCT_ADD T1
         INNER JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID
                                          AND T2.FINPROD_TYPE2 = #{F16}
WHERE T2.FINPROD_MARKET_ID = #{portfolioId}

select
TOTLE_TRADE_ID
from ${tableId} tpd
where tpd.B_TRADE_ID = #{tradeId}
and tpd.IS_CANCEL = #{isCancle}
and tpd.TRADE_STATUS = #{tradeStatus}

SELECT DISTINCT case when T1.TRADE_STATUS = #{TRADE_STATUS_CX} then T1.P_TRADE_ID ELSE T1.TOTLE_TRADE_ID END id, case when T1.TRADE_STATUS = #{TRADE_STATUS_CX} then T1.P_TRADE_ID ELSE T1.TOTLE_TRADE_ID END text FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
T1.FINPROD_TYPE2 = #{FINPROD_TYPE}
#{item}
and (instr(TOTLE_TRADE_ID, #{search}) > 0)

select.if:
select decode(secAcctName,'',secAcctId) as chIld,decode(chIldName,'',secAcctId) as secAcctId, aa.amount + aa.flowAmount as bconShareAmt,aa.* from (
select psp.PORTFOLIO_ID subPortfolioId, pp.PORTFOLIO_NAME subPortfolioName, psp.SEC_ACCT_ID secAcctId, si.sec_acct_name secAcctName, (SELECT NVL(A.FINPROD_ABBR, A.FINPROD_NAME) FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_ADD B ON A.FINPROD_ID = B.FINPROD_ID where A.FINPROD_ID = psp.sec_acct_id) chIldName,
'${value}' ${key}
pp.PARENT_PORTFOLIO_ID portfolioId, SUM(DECODE(psp.HODING_TYPE, '06', psp.AMOUNT*-1, psp.AMOUNT)) AMOUNT, (select nvl(sum(amount),0) from PTL_SEC_POSITION_flow where PORTFOLIO_ID = psp.portfolio_id and sec_acct_id = psp.sec_acct_id and finprod_id = psp.finprod_id and hoding_type='01') flowAmount from PTL_SEC_POSITION psp inner join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID inner join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = psp.PORTFOLIO_ID left join STL_SEC_ACCT_INFO si on si.sec_acct_id = PSP.SEC_ACCT_ID where
psp.HODING_TYPE IN ('03', '05', '06') and pp.PARENT_PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and psp.CDATE = #{dealDate,jdbcType=DATE}
and psp.CDATE < #{dealDate,jdbcType=DATE} AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION tpsp where tpsp.HODING_TYPE = psp.HODING_TYPE and tpsp.PORTFOLIO_ID = psp.PORTFOLIO_ID and tpsp.SEC_ACCT_ID = psp.SEC_ACCT_ID and tpsp.FINPROD_ID = psp.FINPROD_ID and tpsp.CDATE > psp.CDATE and tpsp.CDATE < #{dealDate,jdbcType=DATE} ) /*不存在生效的交易*/ AND NOT EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL tpd left join TRD_PRODUCT_DEAL_ADD tpda on tpda.TRADE_ID = tpd.TRADE_ID WHERE tpd.TRADE_STATUS = '01' AND tpd.IS_CANCEL = 'N' AND #{dealDate,jdbcType=DATE} = tpd.MDATE AND tpd.FINPROD_ID = psp.FINPROD_ID AND psp.PORTFOLIO_ID =tpda.PORTFOLIO_ID AND (( tpd.CHL_ID IS NULL AND psp.sec_acct_id='999999') OR tpd.CHL_ID = psp.SEC_ACCT_ID)) /*不存在流程中的当期或之前的交易*/ AND NOT EXISTS ( SELECT 1 FROM WFL_TRD_PRODUCT_DEAL wtpd left join WFL_TRD_PRODUCT_DEAL_ADD wtpda on wtpda.TRADE_ID = wtpd.TRADE_ID WHERE wtpd.TRADE_STATUS = '01' AND wtpd.IS_CANCEL = 'N'
and wtpd.WORKFLOW_ID != #{workflowId}
AND #{dealDate,jdbcType=DATE} = wtpd.MDATE AND wtpd.FINPROD_ID = psp.FINPROD_ID AND psp.PORTFOLIO_ID =wtpda.PORTFOLIO_ID AND (( wtpd.CHL_ID IS NULL AND psp.sec_acct_id='999999') OR wtpd.CHL_ID = psp.SEC_ACCT_ID))
and fp.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
and fp.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and psp.INV_AIM = #{invAim,jdbcType=VARCHAR}
and psp.SEC_ACCT_ID = #{chlId}
GROUP BY psp.PORTFOLIO_ID, psp.finprod_id, pp.PORTFOLIO_NAME, psp.SEC_ACCT_ID, si.sec_acct_name, pp.PARENT_PORTFOLIO_ID ) aa where AMOUNT > 0

mapper.select:
select
count(1)
from
PTL_CAPACCT_INFO pci


        pci.PORTFOLIO_ID =#{portfolioId}


        and pci.ACCT_NO = #{acctNo}


        and pci.ACCT_TYPE = #{acctType}


        and pci.CCY = #{ccy}

SELECT MAX(T1.SEC_ACCT_ID) FROM PTL_SEC_POSITION T1 WHERE T1.PORTFOLIO_ID = #{portfolioId} AND CDATE < #{mDate, jdbcType=DATE} AND T1.FINPROD_ID=#{finprodId} AND T1.HODING_TYPE=#{holdingType}
AND T1.INV_AIM = #{invAim}
AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION PSP WHERE PSP.PORTFOLIO_ID = T1.PORTFOLIO_ID AND T1.SEC_ACCT_ID = PSP.SEC_ACCT_ID AND T1.FINPROD_ID = PSP.FINPROD_ID AND T1.INV_AIM = PSP.INV_AIM AND PSP.HODING_TYPE = T1.HODING_TYPE AND PSP.CDATE < #{mDate, jdbcType=DATE} AND PSP.CDATE > T1.CDATE )
